#include "conjunto.h"

void inicializar(TConjunto *c) {
  c->cantidad = 0;
}

TBool pertenece(TConjunto c, int x) {
  for (int i = 0; i < c.cantidad; i++) {
    if (c.elementos[i] == x) {
      return VERDADERO;
    }
  }
  return FALSO;
}

void agregar(TConjunto *c, int x) {
  if (pertenece(*c, x) == FALSO) {
    c->elementos[c->cantidad] = x;
    c->cantidad = c->cantidad + 1;
  }
}

int cardinal(TConjunto c) {
  return c.cantidad;
}

#include <stdio.h>
#include "conjunto.h"

int main() {
  TConjunto c;
  int n;
  int x;

  inicializar(&c);
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", &x);
    agregar(&c, x);
  }
  printf("Distintos: %d", cardinal(c));
  return 0;
}
